 vals=[]
 for w,s,u in demos:
  vals += [(fn(r,c,w),1) for r,c in s]+[(fn(r,c,w),0) for r,c in u]
 groups={}
 for v,y in vals: groups.setdefault(v,set()).add(y)
 pure=[v for v,ys in groups.items() if len(ys)==1]
 # labels exact by feature equality, where selected iff belongs to selected values
